import { readFile, readdir } from 'node:fs/promises';
import path from 'node:path';

/**
 * The registry as the site reads it.
 *
 * `registry/*.json` is generated by `scripts/build-registry.mjs` from the
 * library's own `.styles.ts` and `.types.ts` files, so everything on a
 * component page — its variant axes, its defaults, its prop table, its file
 * list — is derived from the source rather than written twice. A prop renamed
 * in `button.types.ts` shows up here on the next `npm run registry`; a prop
 * documented by hand would not.
 *
 * All of this runs at build time. `dynamicParams = false` on the routes means
 * every component page is prerendered, so the filesystem is never touched by a
 * running server.
 */

const repoRoot = path.resolve(process.cwd(), '../..');
const registryDir = path.join(repoRoot, 'registry');

export interface RegistryProp {
  type: string;
  control?: string;
  required: boolean;
  doc: string | null;
  options?: string[];
  default?: unknown;
  source: 'cva' | 'dom' | string;
}

export interface RegistryComponent {
  name: string;
  exported: boolean;
  variants: Record<string, string[]>;
  defaultVariants: Record<string, unknown>;
  slots: string[];
  extends: string[];
  props: Record<string, RegistryProp>;
}

export interface RegistryEntry {
  /** Directory under `src/components`, and the slug in the URL. */
  dir: string;
  name: string;
  type: string;
  files: string[];
  exports: string[];
  dependencies: {
    npm: string[];
    registry: string[];
    shared: string[];
  };
  components: RegistryComponent[];
}

let cached: RegistryEntry[] | null = null;

export async function allComponents(): Promise<RegistryEntry[]> {
  if (cached) return cached;

  const names = (await readdir(registryDir)).filter(
    (file) => file.endsWith('.json') && file !== 'index.json',
  );

  const entries = await Promise.all(
    names.map(async (file) => {
      const raw = await readFile(path.join(registryDir, file), 'utf8');
      return JSON.parse(raw) as RegistryEntry;
    }),
  );

  entries.sort((a, b) => a.name.localeCompare(b.name, 'en'));
  cached = entries;
  return entries;
}

export async function componentBySlug(
  slug: string,
): Promise<RegistryEntry | null> {
  const entries = await allComponents();
  return entries.find((entry) => entry.dir === slug) ?? null;
}

export interface SourceFile {
  /** Path as the registry records it, relative to the repository root. */
  path: string;
  /** Just the file name, for the tab strip. */
  name: string;
  source: string;
}

/**
 * The component's actual source, read from disk.
 *
 * Not a hand-written snippet of "how to use it": the files the CLI would copy
 * into your repository, which is the thing a reader of the Code tab is
 * deciding whether to take.
 */
export async function sourceFiles(entry: RegistryEntry): Promise<SourceFile[]> {
  /* Stories and tests are in the directory but not in the registry's `files`
     list, so this is already the shipped surface only. */
  return Promise.all(
    entry.files.map(async (relative) => ({
      path: relative,
      name: path.basename(relative),
      source: await readFile(path.join(repoRoot, relative), 'utf8'),
    })),
  );
}

/** How many distinct variant axes the whole directory declares. */
export function variantAxisCount(entry: RegistryEntry): number {
  return entry.components.reduce(
    (total, component) => total + Object.keys(component.variants).length,
    0,
  );
}

/** How many props, across every component in the directory. */
export function propCount(entry: RegistryEntry): number {
  return entry.components.reduce(
    (total, component) => total + Object.keys(component.props).length,
    0,
  );
}
